"""Update autogenerated wrapper stubs from probe report required-field discoveries.

Reads ``post_probe_report.json`` (or a specified path) and for each
``informative_error`` result rewrites the matching autogenerated wrapper
function to include the required parameters the API reported back.

Usage:
    python update_wrappers_from_probe.py                   # uses post_probe_report.json in CWD
    python update_wrappers_from_probe.py --report path/to/post_probe_report.json
    python update_wrappers_from_probe.py --dry-run         # print diffs only, no writes
"""

from __future__ import annotations

import argparse
import json
import keyword
import re
import sys
from pathlib import Path
from typing import Any

REPO_ROOT = Path(__file__).resolve().parent
API_CALLS_ROOT = REPO_ROOT / "src" / "britecore_sdk" / "api" / "api_calls"


# ---------------------------------------------------------------------------
# Manual field overrides for endpoints where inferred_required_fields is
# empty but we can determine params from the message text.
# ---------------------------------------------------------------------------
