# Endpoints where we can't reliably determine required params from probe output â€”
# skip updating these and leave them for manual review.
_SKIP_PATHS: set[str] = {
    "/api/v2/claim_exposures/create_exposure",  # "Invalid request" â€” no field info
    "/api/v2/claims/bulk_assign",  # '_schema': ['Invalid input type.']
    "/api/v2/claims/bulk_reassign",
    "/api/v2/claims/bulk_unassign",
    "/api/v2/commissions/write_off_negative_amount",  # "Invalid request"
    "/api/v2/policies/initialize_application_questions",  # "Revision not found."
    "/api/v2/policies/rate_quote_revision",  # internal concatenation error
    # Handwritten wrappers using a post() helper â€” need manual update
    "/api/v2/intacct/get_unexported_claim_transactions_xml",
    "/api/v2/intacct/get_unexported_return_premiums_xml",
}

# For already-parameterized functions that are missing one required field,
# specify which field to inject (path â†’ [missing_field, ...]).
_INJECT_INTO_EXISTING: dict[str, list[str]] = {
    "/api/v2/claim_exposures/add_reserve": ["reserve_details"],
    "/api/v2/claim_exposures/get_exposure_accounting_data": ["exposure_id"],
    "/api/v2/claim_exposures/get_exposure_transactions": ["exposure_id"],
    "/api/v2/claim_exposures/make_multi_exposures_payment": ["payment_details"],
    "/api/v2/claim_exposures/make_payment": ["payment_details"],
}


def _sanitize_identifier(raw: str) -> str:
    """Convert an API field name to a safe Python identifier."""
    text = re.sub(r"[^0-9A-Za-z_]+", "_", raw).strip("_")
    if not text:
        text = "field"
    if text[0].isdigit():
        text = f"f_{text}"
    if keyword.iskeyword(text):
        text = f"{text}_"
    return text


def _module_path_for_endpoint(path: str) -> Path | None:
    """Return the wrapper module path for an API endpoint path."""
    match = re.match(r"^/api/(v[12])/([^/]+)/", path)
    if not match:
        return None
    version, domain = match.groups()
    module_name = re.sub(r"[^0-9A-Za-z_]+", "_", domain).strip("_").lower()
    return API_CALLS_ROOT / version / f"{module_name}.py"


def _load_required_fields(result: dict[str, Any]) -> list[str]:
    """Return required field names for an endpoint from probe result data."""
    path = result["path"]

    if path in _SKIP_PATHS:
        return []

    # Use manually curated overrides first
    if path in _MANUAL_FIELDS:
        return _MANUAL_FIELDS[path]

    # Use probe-inferred fields when available
    inferred = result.get("inferred_required_fields", [])
    if inferred:
        return inferred

    return []


def _build_replacement_function(
    original_text: str,
    api_fields: list[str],
) -> str:
    """Rewrite an autogenerated stub to include discovered required parameters.

    Replaces the no-argument signature and empty request_json with parameterised
    versions while leaving every other line untouched.
    """
    if not api_fields:
        return original_text

    # Build parameter lines:  param_name: Any | None = None,
    py_params: list[tuple[str, str]] = []
    for field in api_fields:
        py_name = _sanitize_identifier(field)
        py_params.append((py_name, field))

    signature_lines = "".join(
        f"    {py_name}: Any | None = None,\n" for py_name, _ in py_params
    )
    signature_lines += "    **kwargs: Unpack[RequestParameters],\n"

    # Build request_json body
    if len(py_params) == 1:
        py_name, api_name = py_params[0]
        json_body = f'    request_json: dict[str, Any] = {{"{api_name}": {py_name}}}\n'
    else:
        inner = "".join(
            f'        "{api_name}": {py_name},\n' for py_name, api_name in py_params
        )
        json_body = f"    request_json: dict[str, Any] = {{\n{inner}    }}\n"

    # Replace signature: `    **kwargs` â†’ `    <params>    **kwargs`
    result = re.sub(
        r"^    \*\*kwargs: Unpack\[RequestParameters\],\n",
        signature_lines,
        original_text,
        count=1,
        flags=re.MULTILINE,
    )

    # Replace empty request_json
    result = re.sub(
        r"    request_json: dict\[str, Any\] = \{\}\n",
        json_body,
        result,
        count=1,
    )

    return result


def _inject_param_into_existing(
    source: str,
    api_path: str,
    new_fields: list[str],
) -> tuple[str, list[str]]:
    """Add missing required fields to an already-parameterized autogenerated function.

    Finds the function that has ``api_path`` in its ``do_request`` call, checks
    which ``new_fields`` are not already in the signature, and inserts them
    just before ``**kwargs`` in both the signature and ``request_json`` body.

    Returns the updated source and a list of human-readable change descriptions.
    """
    changes: list[str] = []
    escaped = re.escape(api_path)

    # Locate the full function block by finding its do_request call
    fn_pattern = re.compile(
        r"(def [a-zA-Z0-9_]+\(\n(?:.*\n)*?    \*\*kwargs: Unpack\[RequestParameters\],\n\) -> Any:\n"
        r"(?:.*\n)*?    request_result = API_CLIENT\.do_request\(\n"
        r"(?:.*\n)*?        path=\"" + escaped + r"\",\n"
        r"(?:.*\n)*?    \))"
    )
    match = fn_pattern.search(source)
    if not match:
        changes.append(f"  SKIP {api_path}: parameterized function block not found")
        return source, changes

    original_block = match.group(1)
    updated_block = original_block

    for field in new_fields:
        py_name = _sanitize_identifier(field)

        # Skip if this param already exists in the signature
        if re.search(rf"    {re.escape(py_name)}: ", updated_block):
            changes.append(f"  NOOP {api_path}: {py_name} already in signature")
            continue

        # Add to signature before **kwargs
        updated_block = re.sub(
            r"(    \*\*kwargs: Unpack\[RequestParameters\],\n\) -> Any:)",
            f"    {py_name}: Any | None = None,\n\\1",
            updated_block,
            count=1,
        )

        # Add to request_json  â€” either inline {} or multiline {}
        # Try multiline: "    }\n" closes the dict
        if "    request_json: dict[str, Any] = {" in updated_block:
            # Add before the closing brace of request_json
            updated_block = re.sub(
                r"(    request_json: dict\[str, Any\] = \{)(.*?)(\n    \})",
                lambda m, field=field, py_name=py_name: m.group(1)
                + m.group(2)
                + f'\n        "{field}": {py_name},'
                + m.group(3),
                updated_block,
                count=1,
                flags=re.DOTALL,
            )
        else:
            changes.append(
                f"  WARN {api_path}: could not locate request_json body for {field}"
            )
            continue

        changes.append(f"  INJECT {api_path} â†’ added {py_name} ('{field}')")

    if original_block != updated_block:
        source = source.replace(original_block, updated_block, 1)

    return source, changes


def _update_module(
    module_path: Path,
    updates: dict[str, list[str]],
    dry_run: bool = False,
) -> list[str]:
    """Apply all discovered-field updates to a single wrapper module.

    Returns a list of human-readable change lines for reporting.
    """
    if not module_path.exists():
        return [f"  SKIP {module_path.name}: file not found"]

    source = module_path.read_text(encoding="utf-8")
    changed = list[str]()

    for api_path, fields in updates.items():
        if not fields:
            changed.append(f"  SKIP {api_path}: no fields to add")
            continue

        # Match the autogenerated function by its docstring path literal
        # Pattern: def FUNC_NAME(\n    **kwargs...\n...\n    """Autogenerated wrapper for ``POST /api/path``."""
        escaped = re.escape(api_path)
        pattern = re.compile(
            r"(def [a-zA-Z0-9_]+\(\n)"  # def signature open
            r"(    \*\*kwargs: Unpack\[RequestParameters\],\n)"  # just **kwargs
            r"(\) -> Any:\n)"  # return type
            r'(    """Autogenerated wrapper for ``POST ' + escaped + r'``\."""\n)'
            r"(    from britecore_sdk\.api\.api_calls import api_client as _api_client\n\n)"
            r"(    request_json: dict\[str, Any\] = \{\}\n)",
        )

        match = pattern.search(source)
        if not match:
            changed.append(
                f"  SKIP {api_path}: pattern not found in {module_path.name}"
            )
            continue

        full_match = match.group(0)
        replacement = _build_replacement_function(full_match, fields)

        if full_match == replacement:
            changed.append(f"  NOOP {api_path}: already has params or no change needed")
            continue

        source = source.replace(full_match, replacement, 1)
        changed.append(f"  UPDATE {api_path} â†’ added {fields}")

    if not dry_run and any(line.startswith("  UPDATE") for line in changed):
        module_path.write_text(source, encoding="utf-8")

    return changed


def _apply_injections(
    module_path: Path,
    inject_map: dict[str, list[str]],
    dry_run: bool = False,
) -> list[str]:
    """Phase 2: inject missing fields into already-parameterized functions."""
    if not module_path.exists():
        return [f"  SKIP {module_path.name}: file not found"]

    source = module_path.read_text(encoding="utf-8")
    original = source
    all_changes: list[str] = []

    for api_path, fields in inject_map.items():
        source, changes = _inject_param_into_existing(source, api_path, fields)
        all_changes.extend(changes)

    if not dry_run and source != original:
        module_path.write_text(source, encoding="utf-8")

    return all_changes


def main(argv: list[str] | None = None) -> int:
    """Entry point for updating autogenerated wrapper stubs from probe report.

    Args:
        argv: Command-line arguments (default: sys.argv).

    Returns:
        Exit code (0 for success, 1 for failure).
    """
    parser = argparse.ArgumentParser(
        description="Update autogenerated wrapper stubs from probe report findings."
    )
    parser.add_argument(
        "--report",
        default="post_probe_report.json",
        help="Path to post_probe_report.json (default: ./post_probe_report.json).",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Print what would change but do not write files.",
    )
    args = parser.parse_args(argv)

    report_path = Path(args.report)
    if not report_path.exists():
        print(f"ERROR: report not found: {report_path}")
        return 1

    data = json.loads(report_path.read_text(encoding="utf-8"))
    results = data.get("results", [])

    # Group informative_error results by module file
    module_updates: dict[Path, dict[str, list[str]]] = {}
    skipped_paths: list[str] = []

    for result in results:
        if result["outcome"] != "informative_error":
            continue

        api_path = result["path"]
        fields = _load_required_fields(result)

        if api_path in _SKIP_PATHS or not fields:
            skipped_paths.append(api_path)
            continue

        module_path = _module_path_for_endpoint(api_path)
        if module_path is None:
            print(f"  WARNING: cannot determine module for {api_path}")
            continue

        module_updates.setdefault(module_path, {})[api_path] = fields

    # Apply updates
    total_updated = 0
    total_injected = 0
    total_skipped = 0

    for module_path, updates in sorted(module_updates.items()):
        print(f"\n{'DRY-RUN ' if args.dry_run else ''}Processing: {module_path.name}")
        changes = _update_module(module_path, updates, dry_run=args.dry_run)
        for line in changes:
            print(line)
            if line.startswith("  UPDATE"):
                total_updated += 1
            elif line.startswith("  SKIP"):
                total_skipped += 1

    # Phase 2: inject into already-parameterized functions
    # Group _INJECT_INTO_EXISTING by module file
    inject_by_module: dict[Path, dict[str, list[str]]] = {}
    for api_path, fields in _INJECT_INTO_EXISTING.items():
        mod = _module_path_for_endpoint(api_path)
        if mod:
            inject_by_module.setdefault(mod, {})[api_path] = fields

    if inject_by_module:
        print("\n--- Phase 2: injecting into already-parameterized functions ---")
        for module_path, inject_map in sorted(inject_by_module.items()):
            print(
                f"\n{'DRY-RUN ' if args.dry_run else ''}Injecting into: {module_path.name}"
            )
            changes = _apply_injections(module_path, inject_map, dry_run=args.dry_run)
            for line in changes:
                print(line)
                if line.startswith("  INJECT"):
                    total_injected += 1
                elif line.startswith("  SKIP"):
                    total_skipped += 1

    print(
        f"\nPaths skipped (no parseable fields or in skip-list): {len(skipped_paths)}"
    )
    for p in skipped_paths:
        print(f"  {p}")

    print(
        f"\n{'[DRY-RUN] ' if args.dry_run else ''}"
        f"Done â€” {total_updated} stub(s) updated, {total_injected} field(s) injected, "
        f"{total_skipped} skipped."
    )

    return 0


if __name__ == "__main__":
    sys.exit(main())
